CREATE TABLE sheet_cai_yi_ji_neng_biao (
  row_id INTEGER PRIMARY KEY,
  character_name TEXT NOT NULL, -- 角色姓名
  skill_name TEXT NOT NULL, -- 技能
  skill_value TEXT -- 数值
);

CREATE TABLE sheet_jian_ding_jian_yi_biao (
  row_id INTEGER PRIMARY KEY,
  display_text TEXT NOT NULL CHECK(TRIM(display_text) <> ''), -- 展示文本
  dice_command TEXT NOT NULL CHECK(TRIM(dice_command) <> '') -- 骰子命令
);

CREATE TABLE sheet_yi_jian_kai_guan_biao (
  row_id INTEGER PRIMARY KEY,
  dang_qian_mo_shi TEXT, -- 当前模式
  is_nsfw TEXT -- 是否NSFW
);
